  alternativas:[{id:"A",texto:"Papila duodenal maior"},{id:"B",texto:"Ducto colédoco"},{id:"C",texto:"Ducto hepático comum"},{id:"D",texto:"Ducto cístico"}],
  gabarito:"D",
  explicacaoGeral:"A alternativa D está correta. Dicas do enunciado: **mulher de 48 anos com icterícia, colúria e acolia (síndrome colestática obstrutiva), dor lombar, perda de 20 kg em 6 meses, dilatação das vias biliares intra e extra-hepáticas, trombose das veias esplênica e mesentérica superior (hipercoagulabilidade paraneoplásica) e massa de 8 cm na cabeça e no corpo do pâncreas**: **adenocarcinoma de pâncreas** com obstrução da via biliar principal. A dilatação intra e extra-hepática indica obstrução **distal ao hepático comum**: no **colédoco** (a porção intrapancreática atravessa a cabeça do pâncreas) ou na **papila duodenal maior** (ampola de Vater). O **ducto cístico** não faz parte da via biliar principal: liga a vesícula ao hepático comum, e sua obstrução causa hidropisia ou colecistite, **sem icterícia**; por isso é a localização **menos provável**. Na obstrução distal por tumor, a vesícula pode estar palpável e indolor (sinal de Courvoisier-Terrier). B (colédoco), C (hepático comum, comprimido em tumores que invadem o hilo) e A (papila) são locais possíveis.",
  explicacoesAlternativas:{},
  referencias:"Townsend CM, Beauchamp RD, Evers BM, Mattox KL. Sabiston Tratado de Cirurgia. Elsevier; Coelho JCU. Aparelho Digestivo: Clínica e Cirurgia. Atheneu.",
  dificuldadeManual:"intermediario", status:"ativa",
  estatisticas:{respostas:0, acertos:0, distribuicaoAlternativas:{}},
